Find all functions  $f: (0, \infty) \to (0, \infty)$  such that
\begin{align*}
f(y(f(x))^3 + x) = x^3f(y) + f(x) 
\end{align*}
for all  $x, y>0$ . 

*Proposed by Jason Prodromidis, Greece*

candidates:
\textbf{Claim 1.} The function  $f$  is strictly increasing. $P\left( x;\dfrac{y}{f(x)^3} \right):f(y+x)=x^3f\left( \dfrac{y}{f(x)^3} \right)+f(x)>f(x)$ . So  $f(x+y)>f(x)$  for all  $x,y>0$ . Hence,  $f$  is strictly increasing.
\textbf{Claim 2.}  $f(1)=1$ . $P(x;yf(z)^3+z):$ \begin{align*}f(yf(x)^3f(z)^3+zf(x)^3+x)&=x^3f(yf(z)^3+z)+f(x)
&=x^3z^3f(y)+x^3f(z)+f(x),\forall x,y,z>0.
\end{align*}
In this argument, we change the role of  $x$  and  $z$ , we have:   $$ f(yf(x)^3f(z)^3+xf(z)^3+z)=x^3z^3f(y)+z^3f(x)+f(z),\forall x,y,z>0. $$   Then for all  $x,y,z>0$ , we have: \begin{align*}
    f(yf(x)^3f(z)^3+zf(x)^3+x)=f(yf(x)^3f(z)^3+xf(z)^3+z)++x^3f(z)+f(x)-x^3f(z)+f(x)
\end{align*}
In this equation, change  $y$  by  $\frac{y}{f(x)^3f(z)^3}$ , we have: \begin{equation}f(y+zf(x)^3+x)=f(y+xf(z)^3+z)+x^3f(z)+f(x)-z^3f(x)-f(z),\forall x,y,z>0.\end{equation}
\begin{enumerate}
\item[ $\bullet$ ] If  $zf(x)^3+x=xf(z)^3+z,\forall x,z>0$ . Then by (1), we get:   $$ x^3f(z)+f(x)=z^3f(x)+f(z),\forall x,z>0. $$  Then  $f(z)(x^3-1)=f(x)(z^3-1),\forall x,z>0$ . Let  $x=2$  and  $z=1$ , then  $f(1)=0$ , this is a contradiction.
\item[ $\bullet$ ] If there exists real numbers  $x_0$  and  $z_0$  such that  $z_0f(x_0)^3+x_0>x_0f(z_0)^3+z_0$ . Let   $$ A=z_0f(x_0)^3+x_0>x_0f(z_0)^3+z_0,B=x_0^3f(z_0)+f(x_0)-z_0^3f(x_0)-f(z_0). $$  In  $(1)$ , change  $y$  by  $y-x_0f(z_0)^3-x_0$ , we have   $$ f(y+A)=f(y)+B,\forall y>x_0f(z_0)^3+x_0. $$  In the equation that problem gives, change  $y$  by  $y+A$ , we have: \begin{align*}f(yf(x)^3+Af(x)^3+x)&=x^3f(y+A)+f(x)=x^3f(y)+f(x)+Bx^3
&=f(yf(x)^3+x)+Bx^3
&=f(yf(x)^3+x)+B+B(x^3-1)
&=f(yf(x)^3+x+A)+B(x^3-1),
\end{align*}
for all  $x>0,y>x_0f(z_0)^3+x_0$ .
In this argument, we change  $x=1$ , we get:  $f(yf(1)^3+Af(1)^3+1)=f(yf(1)^3+1+A)$ . Because function  $f$  is strictly increasing,  $yf(1)^3+Af(1)^3+1=yf(1)^3+1+A$ , so  $f(1)=1$ .
Hence,  $f(1)=1$ .
\end{enumerate}
\textbf{Claim 3.}  $f(n)=n$ , for all positive integers  $n$ . 
In the equation that problem gives, let  $x=1$ , we have: \begin{equation}f(y+1)=f(y)+1,\forall y>0.\end{equation}
So we easily get that  $f(2)=2,f(3)=3,\ldots$  Suppose that  $f(n)=n, n \in \mathbb{Z^+}$ . By equation (2), we have:  $f(n+1)=f(n)+1=n+1$ . So  $f(n)=n$ , for all positive integers  $n$ .
\textbf{Claim 4.}  $f(n)=n$ , for all positive rational number  $n$ .
\end{proof}
\textbf{Claim 4.}  $f(n)=n$ , for all positive rational number  $n$ .
For all positive integers  $m,n$ ; change  $x=n$  and  $y=\frac{m}{n}$  in the equation that problem gives, we get:   $$ f(mn^2+n)=n^3f\left( \dfrac{m}{n} \right)+f(n)\rightarrow mn^2+n=n^3f\left( \dfrac{m}{n} \right)+n\rightarrow f\left( \dfrac{m}{n}\right)=\dfrac{m}{n}. $$   Then  $f(n)=n$ , for all positive rational number  $n$ .
\textbf{Claim 5.}  $f(x)=x$ , for all positive real number  $x$ .
For all positive real number  $x$ , there exists two rational sequence  $(a_n)$  and  $(b_n)$  such that  $(a_n)$  is increasing,  $(b_n)$  is decreasing and  $\lim a_n=\lim b_n=x$ . Because function  $f$  is strictly increasing, then   $$ a_n\leq x\leq b_n\rightarrow f(a_n)\leq f(x)\leq f(b_n)\rightarrow a_n\leq f(x)\leq b_n. $$   Let  $n\longrightarrow +\infty$ , by Squeeze theorem, we get:  $f(x)=x$  (as  $\lim a_n=\lim b_n=x$ ).

Conclusion,  $f(x)=x$ , for all positive real number  $x$ .

Let  $E$  be the point of intersection of  $CX$  with  $AB$ , and let  $F$  be the point of intersection of  $OX$  and  $AB$ . 

Note that  $CE$  is the  $C$ -symmedian of  $ABC$ . Moreover,  $F$  is the midpoint of  $AB$  and  $OF\perp AB$ , while  $Y$  is the midpoint of  $CD$  and  $OY\perp CX$ . 

The points  $A,X,B,O$  lie on the circle  $\omega'$  with diameter  $OX$ , which passes through  $Y$ , since  $O\widehat{Y}X=90^\circ=O\widehat{A}X=O\widehat{B}X$ . Since  $BF$  is the altitude to the hypotenuse od the right triangle  $XBO$  and the quadrilateral  $EFOY$  is cyclic, it follows that  $XB^2=XF\cdot XO=XE\cdot XY$  (from the power of the point  $X$  with respect to the circumcircle of  $EFOY$ ).

The power of the point  $X$  with respect to  $\omega$  is equal to  $XB^2=XD\cdot XC$ , and so  $XE\cdot XY=XD\cdot XC$ .  Hence $\dfrac{XD}{XY}=\dfrac{XE}{XC}$ .

Since  $AE$  is parallel to  $ZC$ , it follows that $\dfrac{XE}{XC}=\dfrac{XA}{XZ}$ ,

and so $\dfrac{XD}{XY}=\dfrac{XA}{XZ}$ .

Hence  $AD$  is parallel to  $ZY$ , and so  $YM$  is parallel to  $DA$ , where  $M$  is the point of intersection of  $ZY$  with  $AC$ . 

Since  $Y$  is the midpoint of  $CD$ , it follows that  $M$  is the midpoint of  $CA$ , as desired.

For more properties of point  $Y$ , see the article  [Midpoint of Symmedian Chord](https://www.awesomemath.org/wp-pdf-files/math-reflections/mr-2021-04/mr_4_2021_midpoint_of_symmedian_chord.pdf). Compare this BMO problem to Problem 12, on page 18 of this article ([Peru TST 2006/4,](https://artofproblemsolving.com/community/c6h88554p516508) [Dutch IMO TST 2019 2.3](https://artofproblemsolving.com/community/c6h1887609p12867641)).

